import paramiko
c = paramiko.SSHClient()
c.set_missing_host_key_policy(paramiko.AutoAddPolicy())
c.connect('46.202.154.25', 22, 'root', '2N00py123+++')

# Create root build.gradle with plugin
root_build = '''buildscript {
    ext {
        kotlinVersion = "1.9.20"
        capacitorAndroidVersion = "5.7.0"
    }
    repositories {
        google()
        mavenCentral()
    }
    dependencies {
        classpath("com.android.tools.build:gradle:8.2.0")
    }
}

allprojects {
    repositories {
        google()
        mavenCentral()
    }
}

task clean(type: Delete) {
    delete rootProject.buildDir
}
'''

sftp = c.open_sftp()
with sftp.file('/tmp/build.gradle', 'w') as f:
    f.write(root_build)

c.exec_command('cp /tmp/build.gradle /opt/areloria/client/android/build.gradle')

# Also add gradle.properties
c.exec_command("""echo 'org.gradle.jvmargs=-Xmx2048m
android.useAndroidX=true
android.enableJetifier=true' > /opt/areloria/client/android/gradle.properties""")

print("Root build.gradle created!")

c.close()
EOF

